-- MySQL 8 方言版建表脚本，仅供 Testcontainers 集成测试使用（application-unit-test-tc.yaml 引用）
--
-- 说明：现有 create_tables.sql 是 H2 方言（双引号标识符、GENERATED BY DEFAULT AS IDENTITY、bit DEFAULT FALSE 等），
-- MySQL 8 无法直接执行，所以单独维护本文件。目前只包含示例测试（部门）用到的 system_dept 一张表；
-- 后续给其它模块/表写 Testcontainers 测试时，按同样方式把对应表的 DDL 翻译后追加到这里即可。
CREATE TABLE IF NOT EXISTS `system_dept` (
    `id` bigint NOT NULL AUTO_INCREMENT,
    `name` varchar(30) NOT NULL DEFAULT '',
    `parent_id` bigint NOT NULL DEFAULT 0,
    `sort` int NOT NULL DEFAULT 0,
    `leader_user_id` bigint DEFAULT NULL,
    `phone` varchar(11) DEFAULT NULL,
    `email` varchar(50) DEFAULT NULL,
    `status` tinyint NOT NULL,
    `creator` varchar(64) DEFAULT '',
    `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updater` varchar(64) DEFAULT '',
    `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `deleted` bit(1) NOT NULL DEFAULT b'0',
    `tenant_id` bigint NOT NULL DEFAULT 0,
    PRIMARY KEY (`id`)
) ENGINE = InnoDB COMMENT '部门表';

CREATE TABLE IF NOT EXISTS `system_nav_link` (
    `id` bigint NOT NULL AUTO_INCREMENT,
    `name` varchar(50) NOT NULL,
    `url` varchar(500) NOT NULL,
    `category` tinyint NOT NULL,
    `icon` varchar(100) DEFAULT '',
    `sort` int NOT NULL DEFAULT 0,
    `status` tinyint NOT NULL DEFAULT 0,
    `remark` varchar(500) DEFAULT NULL,
    `creator` varchar(64) DEFAULT '',
    `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updater` varchar(64) DEFAULT '',
    `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `deleted` bit(1) NOT NULL DEFAULT b'0',
    `tenant_id` bigint NOT NULL DEFAULT 0,
    PRIMARY KEY (`id`)
) ENGINE = InnoDB COMMENT '常用网址导航表';

CREATE TABLE IF NOT EXISTS `system_todo` (
    `id` bigint NOT NULL AUTO_INCREMENT,
    `user_id` bigint NOT NULL,
    `title` varchar(100) NOT NULL,
    `content` varchar(1000) DEFAULT NULL,
    `priority` tinyint NOT NULL DEFAULT 2,
    `status` tinyint NOT NULL DEFAULT 0,
    `deadline` datetime DEFAULT NULL,
    `finish_time` datetime DEFAULT NULL,
    `remark` varchar(500) DEFAULT NULL,
    `creator` varchar(64) DEFAULT '',
    `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    `updater` varchar(64) DEFAULT '',
    `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    `deleted` bit(1) NOT NULL DEFAULT b'0',
    `tenant_id` bigint NOT NULL DEFAULT 0,
    PRIMARY KEY (`id`),
    KEY `idx_user_id` (`user_id`),
    KEY `idx_deadline` (`deadline`)
) ENGINE = InnoDB COMMENT '个人待办表';
